import {featureFlags,enabledServices,enabledRoles,serviceVisible,roleVisible,visibleOrders,visibleNotifications} from './features.js';
import {trackingStages,trackingView} from './tracking.js';
import {restaurant,menu,foodSteps,foodStatusLabel,cartItems,cartSubtotal,setCartQuantity,createFoodOrder,transitionFood,registerDemoProfile,foodCourierQueue,normalizeFoodState} from './food.js';
import type {FoodAction} from './food.js';
import type {Role,ProfessionalRole,ServiceId,Service,Order,OrderInput,DemoState,FoodRole,OrderStatus} from './types.js';
import {STORAGE_KEY,services,deliveryTypes,updateDeliveryLabels,professionals,steps,initialState,quote,statusLabel,createOrder,acceptOrder,advanceOrder,cancelOrder,rateOrder,notify} from './domain.js';
const foodActionLabels:Record<FoodAction,string>={restaurantAccept:'Aceitar pedido',startPreparing:'Iniciar preparo',markReady:'Marcar como pronto',courierAccept:'Aceitar entrega',goPickup:'Ir buscar pedido',confirmPickup:'Confirmar retirada',startDelivery:'Sair para entrega',deliver:'Confirmar entrega concluída',cancel:'Cancelar pedido demo',restaurantReject:'Recusar pedido'};
const paths:Record<string,string>={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',orders:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H6a3 3 0 0 0 0 6h14v12H6a3 3 0 0 1-3-3V6"/><path d="M16 12h5v5h-5z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3Z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',back:'<path d="m15 5-7 7 7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',box:'<path d="m3 7 9-5 9 5-9 5ZM3 7v10l9 5 9-5V7M12 12v10M8 4l9 5"/>',car:'<path d="m4 9 2-6h12l2 6M3 10h18v9H3zM5 19v3M19 19v3M6 14h2M16 14h2"/>',bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-9h5l4 9M8 5h4M12 8l3 9H5M15 8l-1-5h3"/>',help:'<path d="M3 14v-3a9 9 0 0 1 18 0v3M3 13h3v8H3zM18 13h3v8h-3zM18 21h-6"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 11 3 3 5-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>',lab:'<path d="M9 3h6M10 3v6L4 19a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2L14 9V3M7 15h10"/>',logout:'<path d="M10 3H4v18h6M8 12h13m-5-5 5 5-5 5"/>',settings:'<path d="m9 3-1 3-3 1v4l-2 1 2 2v3l3 1 1 3h6l1-3 3-1v-3l2-2-2-1V7l-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',chart:'<path d="M3 3v18h18M7 17V9M12 17V5M17 17v-6"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 7"/>',coupon:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Z"/><path d="m9 15 6-6M9 9h.01M15 15h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',alert:'<path d="m12 3 10 18H2ZM12 9v5M12 17h.01"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 11 6-4m-6 6 6 4"/>',money:'<rect x="2" y="5" width="20" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M6 12h.01M18 12h.01"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',heart:'<path d="M20 4c-4-3-8 2-8 2S8 1 4 4c-6 5 8 17 8 17S26 9 20 4Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};
const icon=(name:string,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.box}</svg>`;
const brand=()=>`<div class="brand"><svg class="pin" viewBox="0 0 48 58" aria-hidden="true"><path d="M24 1C8 1-1 16 6 30l18 27 18-27C49 16 40 1 24 1Z"/><circle fill="white" cx="24" cy="22" r="9"/></svg>TitoJá</div>`;
const money=(x:number)=>Number(x).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const esc=(x:unknown)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'} as Record<string,string>)[c]);
const date=(x:string)=>new Date(x).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const serviceFor=(id:string)=>services.find(s=>s.id===id)||services[2];
function art(service:Service,extra=''){if(service.id==='beer')return `<div class="service-art beer-art ${extra}" role="img" aria-label="${service.name}"><img src="./assets/beer-3d.png" alt="" aria-hidden="true" decoding="async"></div>`;const [x,y,w,h]=service.crop;return `<div class="service-art ${extra}" role="img" aria-label="${service.name}" style="aspect-ratio:${w}/${h};background-size:${711/w*100}% auto;background-position:${x/(711-w)*100}% ${y/(1536-h)*100}%"></div>`;}
let state:DemoState;try{state=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(state?.version!==1)state=initialState();else updateDeliveryLabels(state);}catch{state=initialState();}
if(!roleVisible(state.role))state.role='client';
let tabFilter='all',adminView='dashboard',ratingValue=0,ratingTags:string[]=[],toastTimer:ReturnType<typeof setTimeout>,modalFocus:Element|null=null,draft:Partial<OrderInput>|null=null;
const app=document.querySelector<HTMLDivElement>('#app')!,modal=document.querySelector<HTMLDialogElement>('#modal')!;
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('O armazenamento local está indisponível. Seus testes ficarão nesta sessão.');}}
function toast(text:string){const el=document.querySelector<HTMLDivElement>('#toast')!;el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function currentRoute(){const a=location.hash.replace(/^#\/?/,'').split('/');return {role:(a[0]||state.role) as Role,page:a[1]||'home',id:a[2]};}
function go(page='home',role:Role=state.role,id=''){modal.close();location.hash=`/${role}/${page}${id?'/'+id:''}`;}
function head(title:string,subtitle='',back=true){return `<div class="page-head">${back?`<button class="back" data-action="home" aria-label="Voltar ao início">${icon('back')}</button>`:''}<div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div></div>`;}
function status(o:Order){return `<span class="status ${o.status}">${o.status==='completed'?icon('check'):''}${statusLabel(o)}</span>`;}
function orderCard(o:Order){return `<button class="order-card" data-action="order" data-id="${o.id}"><div class="thumb">${art(serviceFor(o.service))}</div><div class="grow"><div class="order-title">${serviceFor(o.service).name}${o.food?` · ${o.id}`:''}</div><div class="order-route">${esc(o.from.split(',')[0])} → ${esc(o.to.split(',')[0])}</div></div><div class="order-right"><div class="price">${money(o.price)}</div>${status(o)}</div>${icon('chevron')}</button>`;}
function helpCard(){return `<button class="help-card" data-action="help"><div class="help-icon">${icon('help')}</div><div class="grow"><strong>Precisa de ajuda?</strong><p>Conheça a demonstração</p></div>${icon('chevron')}</button>`;}
function nav(role:Role,page:string){if(featureFlags.deliveryFocus){const items=role==='client'?[['home','home','Início'],['orders','orders','Pedidos'],['wallet','wallet','Pagamentos'],['profile','user','Perfil']]:role==='restaurant'?[['home','home','Cozinha'],['orders','orders','Histórico'],['wallet','wallet','Vendas'],['profile','user','Perfil']]:role==='courier'?[['home','home','Início'],['orders','orders','Entregas'],['wallet','wallet','Ganhos'],['profile','user','Perfil']]:[['home','chart','Painel'],['orders','orders','Pedidos'],['wallet','wallet','Resumo'],['profile','user','Perfil']];return items.map(([id,ico,label])=>`<a href="#/${role}/${id}" class="${page===id||page==='order'&&id==='orders'?'active':''}">${icon(ico)}<span>${label}</span></a>`).join('');}const items=role==='client'?[['home','home','Início'],['orders','orders','Pedidos'],['wallet','wallet','Carteira'],['profile','user','Perfil']]:role==='admin'?[['home','chart','Painel'],['orders','orders','Pedidos'],['wallet','wallet','Finanças'],['profile','user','Perfil']]:[['home','home','Início'],['orders','orders','Histórico'],['wallet','wallet','Ganhos'],['profile','user','Perfil']];return items.map(([id,ico,label])=>`<a href="#/${role}/${id}" class="${page===id||page==='order'&&id==='orders'?'active':''}">${icon(ico)}<span>${label}</span></a>`).join('');}
function render(persist=true){const route=currentRoute();if(!roleVisible(route.role)){state.role='client';go('home','client');return;}if(featureFlags.deliveryFocus&&route.page==='apply'){go('profile',route.role);return;}state.role=route.role;if(persist)save();let body;if(!state.loggedIn){body=loginPage();}else{if(route.page==='order'){const order=visibleOrders(state).find(o=>o.id===route.id);body=order?orderPage(order):empty('Pedido não encontrado','Volte ao início e escolha um pedido.');}else if(route.page==='food')body=state.role==='client'?foodPage():restaurantPage();else if(route.page==='menu')body=foodMenuPage();else if(route.page==='cart')body=foodCartPage();else if(route.page==='checkout')body=foodCheckoutPage();else if(route.page==='orders')body=ordersPage();else if(route.page==='wallet')body=walletPage();else if(route.page==='profile')body=profilePage();else if(route.page==='apply')body=applyPage();else body=state.role==='client'?homePage():state.role==='admin'?adminPage():state.role==='restaurant'?restaurantPage():professionalPage();}app.innerHTML=`<div class="demo-top"><strong>MODO DEMONSTRAÇÃO</strong> · Dados fictícios. ${featureFlags.deliveryFocus?'Nenhuma entrega ou cobrança real.':'Nenhuma corrida, entrega ou cobrança real.'}</div><header class="desktop-header"><a href="#/${state.role}/home" aria-label="TitoJá início">${brand()}</a><nav class="header-links">${nav(state.role,route.page).replaceAll(/<svg[\s\S]*?<\/svg>/g,'')}</nav><button class="profile-chip" data-action="profile"><span class="avatar">CD</span><span>Olá, ${esc(state.name)}!</span>${icon('down')}</button></header><main class="workspace"><div class="test-toolbar"><span class="test-label">${icon('lab')} Explore a demonstração</span><div class="role-picker" aria-label="Perfil de teste">${[['client','Cliente'],['restaurant','Restaurante'],['courier','Entregador'],['driver','Motorista'],['admin','Admin']].filter(([r])=>roleVisible(r as Role)).map(([r,t])=>`<button data-action="role" data-role="${r}" class="${state.role===r?'active':''}" aria-pressed="${state.role===r}">${t}</button>`).join('')}</div></div>${state.loggedIn?demoIdentityBar():''}${body}</main>${state.loggedIn?`<nav class="bottom-nav" aria-label="Navegação principal">${nav(state.role,route.page)}</nav>`:''}`;}
function legacyHomePage(){const active=visibleOrders(state).find(o=>!['completed','cancelled'].includes(o.status));return `<div class="client-layout"><section><div class="mobile-brand">${brand()}<button class="icon-button ${state.notifications.some(n=>!n.read)?'badge-dot':''}" data-action="notifications" aria-label="Notificações">${icon('bell')}</button></div><div class="hello"><div><h1>Olá, ${esc(state.name)}!</h1><p class="muted hello-slogan">Seu pedido. Sua corrida. Seu destino.</p></div><button class="icon-button ${state.notifications.some(n=>!n.read)?'badge-dot':''}" data-action="notifications" aria-label="Notificações">${icon('bell')}</button></div><button class="location" data-action="addresses">${icon('pin','location-pin')}<div class="grow"><span>Sua localização de teste</span><strong>Centro, Castanhal</strong></div>${icon('down')}</button>${active?`<div class="section-title"><h2>Seu pedido em andamento</h2></div><div style="margin-bottom:25px">${orderCard(active)}</div>`:''}<div class="section-title"><h2>O que você precisa hoje?</h2></div><div class="services-primary">${services.slice(0,3).map(s=>`<button class="service-card" data-action="request" data-service="${s.id}">${art(s)}<h3>${s.name}</h3><p>${s.desc}</p><span class="go">${icon('chevron')}</span></button>`).join('')}</div><div class="services-secondary">${services.slice(3).map(s=>`<button class="service-card" data-action="${s.id==='food'?'food-open':s.id==='documents'?'request':'soon'}" data-service="${s.id}">${!['documents','food'].includes(s.id)?'<span class="soon">Em breve</span>':''}${art(s)}<h3>${s.name}</h3><span class="go">${icon('chevron')}</span></button>`).join('')}</div><div class="promo"><div class="promo-copy"><h2>Sua primeira entrega<br>com desconto</h2><p>Use o cupom <strong>BEMVINDO</strong></p><button class="primary" data-action="request" data-service="delivery">Pedir agora</button></div>${art({...services[2],crop:[423,874,213,160]})}</div><div class="section-title"><h2>Pedidos recentes</h2><a href="#/client/orders">Ver todos</a></div><div class="stack">${state.orders.slice(0,2).map(orderCard).join('')}</div><div class="mobile-only">${helpCard()}</div></section><aside class="aside"><div class="aside-box wallet-mini"><div class="row between"><h3>Sua carteira</h3>${icon('wallet')}</div><p>Saldo disponível · simulado</p><div class="balance">${money(state.balance)}</div><a href="#/client/wallet">Ver minha carteira</a></div><div class="aside-box"><h3>Seu dia, mais fácil</h3><p>Da primeira corrida à última entrega.</p><div class="benefit">${icon('shield')}<div><strong>Tranquilidade no caminho</strong><p>Acompanhe cada etapa do seu pedido</p></div></div><div class="benefit">${icon('pin')}<div><strong>Feito para sua cidade</strong><p>Castanhal é o cenário desta demo</p></div></div><div class="benefit">${icon('heart')}<div><strong>Gente que cuida</strong><p>Avalie sua experiência ao finalizar</p></div></div></div>${helpCard()}<p class="aside-note">Uma experiência para testar.<br>Todos os valores, pessoas, placas e trajetos são fictícios. Nenhum serviço é contratado.</p></aside></div>`;}
function empty(title:string,desc:string){return `<div class="empty">${icon('box')}<h3>${title}</h3><p>${desc}</p><button class="primary" data-action="home">Voltar ao início</button></div>`;}
function ordersPage(){let orders=visibleOrders(state).filter(o=>state.role==='client'||state.role==='admin'||(state.role==='restaurant'&&!!o.food)||o.professional===state.role);if(tabFilter==='active')orders=orders.filter(o=>!['completed','cancelled'].includes(o.status));if(tabFilter==='completed')orders=orders.filter(o=>o.status==='completed');if(tabFilter==='cancelled')orders=orders.filter(o=>o.status==='cancelled');return `<div class="content-page">${head('Seus pedidos','Acompanhe e relembre suas experiências de teste')}<div class="tabs">${[['all','Todos'],['active','Em andamento'],['completed','Concluídos'],['cancelled','Cancelados']].map(([v,t])=>`<button class="${tabFilter===v?'active':''}" data-action="filter" data-value="${v}">${t}</button>`).join('')}</div><div class="stack">${orders.length?orders.map(orderCard).join(''):empty('Nenhum pedido por aqui','Os pedidos dessa categoria aparecerão aqui.')}</div></div>`;}
function mapView(){return `<div class="map" aria-label="Mapa ilustrativo, sem localização real"><svg class="map-lines" viewBox="0 0 500 270" preserveAspectRatio="none" aria-hidden="true"><path fill="#dce8d1" d="M0 0h120l55 85-60 78H0ZM380 155l120-50v165H347Z"/><path stroke="#fff" stroke-width="20" fill="none" d="M0 57h500M0 130l500-14M0 212l500-15M80 0l40 270M223 0l-20 270M350 0l16 270M460 0l-20 270"/><path stroke="#dfe4dd" stroke-width="2" fill="none" d="M0 57h500M0 130l500-14M0 212l500-15M80 0l40 270M223 0l-20 270M350 0l16 270"/><path stroke="#ff782e" stroke-width="7" stroke-linejoin="round" fill="none" d="M132 171l-8-43 233-9-2-43h30"/><path stroke="#fff" stroke-width="2" stroke-dasharray="2 8" fill="none" d="M132 171l-8-43 233-9-2-43h30"/></svg><div class="map-place a">CENTRO</div><div class="map-place b">JADERLÂNDIA</div><div class="map-place c">CASTANHAL</div><div class="map-marker start">${icon('car')}</div><div class="map-marker end">${icon('pin')}</div><span class="map-label">Mapa ilustrativo · trajeto simulado</span></div>`;}
function routePoints(o:{from?:string;to?:string}){return `<div class="route-points"><div class="route-point"><i></i><div><p>Origem</p><strong>${esc(o.from)}</strong></div></div><div class="route-point"><i></i><div><p>Destino</p><strong>${esc(o.to)}</strong></div></div></div>`;}
function nextLabel(o:Order){return ({accepted:'Confirmar chegada à origem',arrived:o.kind==='ride'?'Confirmar embarque':'Confirmar coleta',boarded:'Iniciar corrida',collected:'Sair para entrega',ongoing:o.kind==='ride'?'Finalizar corrida':'Confirmar entrega',searching:'Aguardar',completed:'Concluído',cancelled:'Cancelado'} as Partial<Record<OrderStatus,string>>)[o.status];}
function orderPage(o:Order){if(o.food)return foodOrderPage(o);const p=o.professional&&professionals[o.professional],canAdvance=state.role===o.professional&&!['completed','cancelled'].includes(o.status);return `<div class="content-page">${head(`${serviceFor(o.service).name} ${o.id}`,`${date(o.created)} · ${o.distance} km · ${o.minutes} min estimados`)}<div class="tracking-layout"><div class="stack">${mapView()}<div class="card"><div class="row between"><h3>${statusLabel(o)}</h3>${status(o)}</div>${o.status==='searching'?`<p class="muted small" style="margin-top:12px">Pedido pronto! Para continuar o teste, abra o perfil ${o.kind==='ride'?'Motorista':'Entregador'}, fique online e aceite o pedido.</p><button class="primary full" style="margin-top:18px" data-action="role" data-role="${o.kind==='ride'?'driver':'courier'}">Testar como ${o.kind==='ride'?'motorista':'entregador'}</button>`:''}${p?`<div class="professional-card"><div class="avatar">${p.initials}</div><div class="grow"><strong>${p.name}</strong><p>${o.service==='car'?p.car:p.vehicle}</p><p>Placa fictícia ${p.plate}</p></div><span class="stars">★ ${p.rating}</span></div>`:''}${o.status!=='cancelled'?`<div class="step-list">${steps[o.kind].slice(1).map((s,i)=>{const current=steps[o.kind].indexOf(o.status);return `<div class="step-item ${current>i+1?'done':current===i+1?'current':''}"><i>${current>i+1?'✓':i+1}</i><span>${statusLabel({...o,status:s})}</span></div>`;}).join('')}</div>`:'<div class="notice" style="margin-top:15px">Pedido cancelado. Nenhuma cobrança real foi feita.</div>'}${canAdvance?`<button class="primary full" data-action="advance" data-id="${o.id}">${nextLabel(o)}</button>`:''}${o.status==='completed'&&state.role==='client'?`<button class="primary full" data-action="rating" data-id="${o.id}">${o.rating?'★ '+o.rating+' · Ver sua avaliação':'Avaliar experiência'}</button>`:''}</div></div><div class="stack"><div class="card"><h3>Detalhes do pedido</h3>${routePoints(o)}${o.kind==='delivery'?`<div class="notice info">${esc(o.deliveryType)}${o.note?` · ${esc(o.note)}`:''}</div>`:''}<div class="divider"></div><div class="summary-line"><span class="muted">Pagamento simulado</span><strong>${esc(o.payment)}</strong></div><div class="summary-line"><span class="muted">Distância estimada</span><strong>${o.distance} km</strong></div><div class="summary-line total"><span>Total demo</span><span>${money(o.price)}</span></div><p class="small muted" style="margin-top:8px">Preço e trajeto fictícios, apenas para teste.</p></div>${!['completed','cancelled'].includes(o.status)?`<div class="card stack"><button class="secondary full" data-action="share" data-id="${o.id}">${icon('share')} Compartilhar · demo</button><button class="secondary full danger" data-action="sos">${icon('shield')} SOS · somente demonstração</button><button class="text-button" data-action="cancel" data-id="${o.id}">Cancelar pedido</button></div>`:''}${helpCard()}</div></div></div>`;}
function legacyProfessionalPage(){const role=state.role as ProfessionalRole,p={...professionals[role],name:role==='courier'?esc(state.demoProfiles.courier.name):professionals[role].name},active=state.orders.find(o=>o.professional===role&&!['completed','cancelled'].includes(o.status)),queue=state.orders.filter(o=>!o.food&&o.status==='searching'&&o.kind===(role==='driver'?'ride':'delivery')&&!o.rejectedBy?.includes(role)).concat(role==='courier'?foodCourierQueue(state):[]);return `<div class="content-page">${head(role==='driver'?'Painel do motorista':'Painel do entregador','Tudo pronto para mais um bom caminho',false)}<div class="professional-head"><div><span class="small">Olá, ${p.name}</span><h2>${state.online[role]?'Você está online':'Hora de começar?'}</h2><p>${state.online[role]?'Disponível para pedidos de teste':'Fique online para receber pedidos simulados'}</p></div><button class="switch ${state.online[role]?'on':''}" role="switch" aria-checked="${state.online[role]}" data-action="online"><span>${state.online[role]?'Online':'Offline'}</span><i></i></button></div><div class="metrics"><div class="metric"><span>Hoje · demo</span><strong>${money(earnings(role))}</strong><small>${state.orders.filter(o=>o.professional===role&&o.status==='completed').length} pedidos concluídos</small></div><div class="metric"><span>Sua avaliação</span><strong>4,9 <span style="color:#efaa3b">★</span></strong><small>Perfil fictício</small></div><div class="metric"><span>Na semana · demo</span><strong>${money(earnings(role)+246.5)}</strong><small>Valores simulados</small></div></div>${active?active.food?foodWorkCard(active):`<div class="section-title"><h2>Seu pedido atual</h2></div><div style="margin-bottom:22px">${orderCard(active)}</div><button class="primary full" data-action="order" data-id="${active.id}">Continuar atendimento</button>`:`<div class="section-title"><h2>Pedidos disponíveis</h2><button class="text-button" data-action="restore-queue">Atualizar fila</button></div>${!state.online[role]?`<div class="card empty">${icon('clock')}<h3>Você está offline</h3><p>Ative o botão acima para ver a fila de teste.<br>Crie um pedido no perfil Cliente para começar.</p></div>`:queue.length?`<div class="stack">${queue.map(o=>o.food?foodOfferCard(o):`<div class="request-card"><div class="row between"><div><h3>${serviceFor(o.service).name}</h3><p class="small muted">${o.id} · ${o.distance} km · ${o.minutes} min</p></div><span class="price">${money(o.price)}</span></div>${routePoints(o)}${o.kind==='delivery'?`<div class="notice info">${esc(o.deliveryType)} · Confirmação fictícia na entrega</div>`:''}<div class="actions"><button class="secondary" data-action="reject" data-id="${o.id}">Recusar</button><button class="primary" data-action="accept" data-id="${o.id}">Aceitar pedido</button></div></div>`).join('')}</div>`:`<div class="card empty">${icon('box')}<h3>Tudo tranquilo por aqui</h3><p>Crie um pedido no perfil Cliente e volte para aceitar.</p><button class="primary" data-action="role" data-role="client">Ir para o perfil Cliente</button></div>`}`}<div class="insight">${icon('lab')}<p>O modo de teste permite alternar entre cliente e profissional. Os dados ficam apenas neste navegador.</p></div></div>`;}
function earnings(role:Role){if(featureFlags.deliveryFocus)return visibleOrders(state).filter(o=>o.food&&o.status==='completed'&&(role==='restaurant'||o.professional===role)).reduce((sum,o)=>sum+(role==='restaurant'?o.food!.subtotal:o.food!.deliveryFee),0);if(role==='restaurant')return state.orders.filter(o=>o.food&&o.status==='completed').reduce((sum,o)=>sum+o.food!.subtotal,0);return state.orders.filter(o=>o.professional===role&&o.status==='completed').reduce((s,o)=>s+(o.food?o.food.deliveryFee:o.price*.85),0);}
function legacyWalletPage(){if(state.role==='restaurant')return restaurantWalletPage();if(state.role==='admin'){adminView='finance';return adminPage();}const pro=state.role!=='client';return `<div class="content-page">${head(pro?'Seus ganhos':'Sua carteira',pro?'Acompanhe seus ganhos fictícios':'Tudo sobre seu saldo de demonstração')}<div class="wallet-hero"><div class="row between"><p>${pro?'Disponível para saque · demo':'Saldo disponível · demo'}</p>${icon('wallet')}</div><h1>${money(pro?earnings(state.role):state.balance)}</h1><button class="secondary" data-action="${pro?'withdraw':'topup'}">${icon('plus')}${pro?'Simular saque':'Adicionar saldo de teste'}</button></div>${pro?`<div class="metrics"><div class="metric"><span>Hoje</span><strong>${money(earnings(state.role))}</strong></div><div class="metric"><span>Semana</span><strong>${money(earnings(state.role)+246.5)}</strong></div><div class="metric"><span>Mês</span><strong>${money(earnings(state.role)+1248.5)}</strong></div></div>`:''}<div class="notice">Nenhum valor nesta tela representa dinheiro real. Não há pagamentos, Pix ou saques conectados.</div><div class="card" style="margin-top:22px"><h3>${pro?'Pedidos concluídos':'Movimentações'}</h3>${pro?state.orders.filter(o=>o.professional===state.role&&o.status==='completed').map(o=>`<div class="transaction"><div class="help-icon">${icon(o.kind==='ride'?'car':'box')}</div><div><strong>${o.id} · ${serviceFor(o.service).name}</strong><p>${date(o.created)} · ${o.food?'Frete ilustrativo · sem comissão definida':'Taxa demo 15%'}</p></div><span class="amount positive">+ ${money(o.food?o.food.deliveryFee:o.price*.85)}</span></div>`).join('')||'<p class="muted small" style="margin-top:20px">Finalize um pedido para registrar ganhos.</p>':state.transactions.map(t=>`<div class="transaction"><div class="help-icon">${icon(t.amount>0?'plus':'orders')}</div><div><strong>${esc(t.label)}</strong><p>${date(t.date)} · Simulação</p></div><span class="amount ${t.amount>0?'positive':''}">${t.amount>0?'+ ':''}${money(t.amount)}</span></div>`).join('')}</div></div>`;}
function legacyProfilePage(){if(state.role==='restaurant')return restaurantProfilePage();return `<div class="content-page">${head('Seu perfil','Um perfil fictício para explorar o TitoJá')}<div class="card"><div class="profile-hero"><div class="avatar">${state.role==='client'||state.role==='admin'?'CD':professionals[state.role as ProfessionalRole].initials}</div><div><h2>${state.role==='client'||state.role==='admin'?esc(state.demoProfiles.client.name):state.role==='courier'?esc(state.demoProfiles.courier.name):professionals[state.role as ProfessionalRole].name}</h2><p class="small muted" style="margin-top:6px">demo@titoja.exemplo · Conta de teste</p></div></div><div class="profile-menu">${[['user','Editar perfil demo','edit-profile'],['pin','Endereços salvos','addresses'],['bell','Notificações','notifications'],['bike','Quero ser profissional','apply'],['help','Ajuda e sobre a demo','help'],['logout','Sair da demonstração','logout']].map(([i,t,a])=>`<button data-action="${a}">${icon(i)}${t}${icon('chevron')}</button>`).join('')}</div></div><div class="notice" style="margin-top:20px">Não envie CPF, CNH, documentos, dados bancários ou senhas reais. O cadastro é apenas ilustrativo.</div></div>`;}
function applyPage(){const existing=state.applications.find(a=>a.id==='my-demo');return `<div class="content-page">${head('Seja parceiro TitoJá','Cadastre um profissional fictício para testar a aprovação')}<div class="card"><div class="notice">Use somente dados inventados. Não pedimos documentos reais, CPF, CNH ou conta bancária.</div>${existing?`<div style="margin-top:23px"><h3>${esc(existing.name)}</h3><p class="muted small" style="margin-top:7px">${existing.type} · ${existing.vehicle}</p><span class="status ${existing.status==='approved'?'completed':existing.status==='rejected'?'cancelled':''}">${({pending:'Aguardando análise demo',approved:'Aprovado na demonstração',rejected:'Reprovado na demonstração'})[existing.status]}</span><div class="divider"></div><button class="primary" data-action="role" data-role="admin">Testar análise como Admin</button><p class="small muted" style="margin-top:13px">A aprovação atualiza este cadastro. Os perfis Motorista e Entregador já estão liberados para testar.</p></div>`:`<form id="application-form"><label class="field"><span>Nome fictício</span><input name="name" value="Alex Demo" required maxlength="40"></label><div class="form-grid"><label class="field"><span>Modalidade</span><select name="type"><option>Mototáxi</option><option>Carro</option><option>Entregador</option></select></label><label class="field"><span>Veículo fictício</span><input name="vehicle" value="Honda CG · DEMO-004" required maxlength="60"></label></div><div class="notice info" style="margin-top:20px">Documentação: anexos fictícios prontos para revisão. Nenhum arquivo será enviado.</div><button class="primary full" style="margin-top:22px">Enviar cadastro de teste</button></form>`}</div></div>`;}
function loginPage(){return `<div class="login card">${brand()}<h1>Seu dia mais fácil começa aqui</h1><p class="muted">Entre com o perfil de demonstração.</p><form id="login-form"><label class="field"><span>Como quer ser chamado?</span><input name="name" placeholder="Seu nome fictício" value="${esc(state.name)}" required maxlength="30" autocomplete="off"></label><button class="primary full">Entrar na demonstração</button></form><button class="text-button full" data-action="signup" style="margin-top:19px">Criar perfil fictício</button><div class="notice">Sem senha, telefone ou dados reais. Suas alterações ficam apenas neste navegador.</div></div>`;}
const adminTabs=[['dashboard','chart','Visão geral'],['users','users','Usuários'],['professionals','bike','Profissionais'],['rides','car','Corridas'],['deliveries','box','Entregas'],['finance','wallet','Financeiro'],['payments','money','Pagamentos'],['coupons','coupon','Cupons'],['ratings','star','Avaliações'],['complaints','help','Reclamações'],['reports','download','Relatórios'],['settings','settings','Configurações']];
function legacyAdminPage(){let body;const legacyTotal=state.orders.filter(o=>!o.food&&o.status==='completed').reduce((sum,o)=>sum+o.price,0),foodTotal=state.orders.filter(o=>o.food&&o.status==='completed').reduce((sum,o)=>sum+o.price,0),total=state.orders.filter(o=>o.status==='completed').reduce((s,o)=>s+o.price,0),active=state.orders.filter(o=>!['completed','cancelled'].includes(o.status));if(adminView==='dashboard')body=`<div class="metrics"><div class="metric"><span>Pedidos demo</span><strong>${state.orders.length}</strong><small>Todos os perfis</small></div><div class="metric"><span>Em andamento</span><strong>${active.length}</strong><small>Atualizado localmente</small></div><div class="metric"><span>Volume simulado</span><strong>${money(total)}</strong><small>Pedidos concluídos</small></div><div class="metric"><span>Cadastros pendentes</span><strong>${state.applications.filter(a=>a.status==='pending').length}</strong><small>Para análise de teste</small></div></div><div class="card"><div class="section-title"><h3>Movimento da semana</h3><span class="small muted">Exemplo ilustrativo</span></div><div class="chart">${[32,49,38,73,56,86,67].map((h,i)=>`<div class="bar" style="--h:${h}%"><span>${['S','T','Q','Q','S','S','D'][i]}</span></div>`).join('')}</div></div><div class="section-title" style="margin-top:25px"><h3>Últimos pedidos</h3></div><div class="stack">${state.orders.slice(0,4).map(orderCard).join('')}</div>`;
else if(adminView==='users')body=`<div class="card"><h3>Usuários de demonstração</h3>${table(['Nome','Contato fictício','Situação'],[[esc(state.name)+' Demo','demo@titoja.exemplo','<span class="status completed">Ativo</span>'],['Cliente Exemplo','cliente@titoja.exemplo','<span class="status completed">Ativo</span>']])}<p class="small muted">Não há contas reais ou autenticação neste protótipo.</p></div>`;
else if(adminView==='professionals')body=`<div class="card"><h3>Análise de cadastros</h3>${table(['Profissional','Modalidade / veículo','Situação','Ação'],state.applications.map(a=>[esc(a.name),esc(a.type)+'<br><span class="small muted">'+esc(a.vehicle)+'</span>',({pending:'Pendente',approved:'Aprovado',rejected:'Reprovado'})[a.status],a.status==='pending'?`<div class="row"><button class="mini-button approve" data-action="application" data-id="${a.id}" data-value="approved">Aprovar</button><button class="mini-button danger" data-action="application" data-id="${a.id}" data-value="rejected">Reprovar</button></div>`:'<span class="muted">Revisado</span>']))}<div class="notice info">Análise simulada de placeholders. Nenhum documento é recebido ou verificado.</div></div><div class="card" style="margin-top:20px"><h3>Perfis liberados para teste</h3>${table(['Nome','Veículo','Avaliação'],Object.values(professionals).map(p=>[p.name,p.vehicle,p.rating+' ★']))}</div>`;
else if(['rides','deliveries'].includes(adminView)){const orders=state.orders.filter(o=>o.kind===(adminView==='rides'?'ride':'delivery'));body=`<div class="stack">${orders.map(orderCard).join('')||empty('Nenhum pedido nessa categoria','Crie um pedido no perfil Cliente.')}</div>`;}
else if(adminView==='finance')body=`<div class="metrics"><div class="metric"><span>Volume demo</span><strong>${money(total)}</strong></div><div class="metric"><span>Taxa demo · 15%</span><strong>${money(legacyTotal*.15)}</strong></div><div class="metric"><span>Repasse demo</span><strong>${money(legacyTotal*.85)}</strong></div><div class="metric"><span>Pendente demo</span><strong>${money(active.reduce((s,o)=>s+o.price,0))}</strong></div></div><div class="card"><h3>Composição por pedido</h3>${table(['Pedido','Total','Taxa demo','Profissional'],state.orders.filter(o=>o.status==='completed').map(o=>[o.id,money(o.price),o.food?'Não definida':money(o.price*.15),money(o.food?o.food.deliveryFee:o.price*.85)]))}<div class="notice">Comida: ${money(foodTotal)} em pedidos concluídos. Produtos e frete são discriminados no pedido, sem comissão comercial definida. As taxas de 15% acima são exemplos anteriores de corridas/entregas genéricas. Nenhum dado bancário ou pagamento real.</div></div>`;
else if(adminView==='payments')body=`<div class="card"><h3>Conferência de pagamentos</h3>${table(['Pedido','Método','Valor','Situação'],state.orders.filter(o=>o.status==='completed').map(o=>[o.id,o.payment,money(o.price),state.paymentsReviewed?'Conferido demo':'Pendente de conferência demo']))}<button class="primary" data-action="review-payments" ${state.paymentsReviewed?'disabled':''}>${state.paymentsReviewed?'Pagamentos conferidos':'Conferir pagamentos demo'}</button><p class="small muted" style="margin-top:15px">Ação administrativa local, sem movimentação financeira.</p></div>`;
else if(adminView==='coupons')body=`<div class="card"><h3>Cupons de demonstração</h3>${table(['Cupom','Benefício ilustrativo','Status','Ação'],state.coupons.map(c=>[c.id,c.discount,c.active?'Ativo':'Inativo',`<button class="mini-button" data-action="coupon" data-id="${c.id}">${c.active?'Desativar':'Ativar'}</button>`]))}<p class="small muted">Os cupons não alteram os preços simulados nesta versão.</p></div>`;
else if(adminView==='ratings')body=`<div class="card"><h3>Experiências avaliadas</h3>${state.orders.filter(o=>o.rating).map(o=>`<div class="transaction"><div class="help-icon">${icon('star')}</div><div class="grow"><strong>${o.id} · ${serviceFor(o.service).name}</strong><p>${o.tags?.map(esc).join(' · ')||'Sem comentários'}</p></div><strong style="color:#d58d1d">${'★'.repeat(o.rating||0)}</strong></div>`).join('')||'<p class="muted">Sem avaliações.</p>'}</div>`;
else if(adminView==='complaints')body=`<div class="card"><h3>Central de atendimento demo</h3>${state.complaints.map(c=>`<div class="transaction"><div class="grow"><strong>${esc(c.title)}</strong><p>${esc(c.name)} · ${c.status==='open'?'Aberta':'Resolvida na demo'}</p></div><button class="mini-button" data-action="resolve" data-id="${c.id}" ${c.status==='resolved'?'disabled':''}>${c.status==='open'?'Resolver':'Resolvida'}</button></div>`).join('')}<div class="notice" style="margin-top:20px">Não envia mensagens para clientes ou profissionais.</div></div>`;
else if(adminView==='reports')body=`<div class="card"><h3>Relatório de pedidos</h3><p class="muted" style="margin:12px 0 20px">Exporte os ${state.orders.length} pedidos deste navegador em CSV, incluindo os dados fictícios e as alterações feitas durante o teste.</p><button class="primary" data-action="export">${icon('download')} Baixar relatório demo</button><div class="notice info" style="margin-top:20px">O arquivo é gerado localmente e não envia dados para nenhum serviço.</div></div>`;
else body=`<div class="card"><h3>Preferências da demonstração</h3><div class="transaction"><div class="grow"><strong>Notificações internas</strong><p>Mensagens de atualização dentro do app</p></div><button class="switch ${state.settings.notifications?'on':''}" role="switch" aria-checked="${state.settings.notifications}" data-action="setting"><i></i></button></div><div class="summary-line"><span class="muted">Cidade de teste</span><strong>Castanhal · PA</strong></div><div class="summary-line"><span class="muted">Modo de operação</span><strong>Frontend local</strong></div><div class="summary-line"><span class="muted">Versão</span><strong>1.0.0 demo</strong></div><div class="divider"></div><button class="secondary danger" data-action="reset">Restaurar dados fictícios</button><p class="small muted" style="margin-top:12px">Apaga somente as alterações desta demonstração no navegador.</p></div>`;
return `<div class="admin-layout"><nav class="admin-nav" aria-label="Administração">${adminTabs.map(([v,i,l])=>`<button class="${v===adminView?'active':''}" data-action="admin" data-value="${v}">${icon(i)}${l}</button>`).join('')}</nav><section class="admin-content">${head(adminTabs.find(t=>t[0]===adminView)?.[2]||'Painel','Administração · ambiente de demonstração',false)}${body}</section></div>`;}
function table(headers:string[],rows:unknown[][]){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function showModal(title:string,html:string){modalFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!modal.open)modal.showModal();}
function requestModal(service:ServiceId){if(featureFlags.deliveryFocus&&!serviceVisible(service)){toast('Este serviço está oculto nesta etapa.');return;}if(state.orders.some(o=>!['completed','cancelled'].includes(o.status))){showModal('Você já tem um pedido',`<p class="muted">Finalize ou cancele seu pedido atual antes de solicitar outro.</p><button class="primary full" data-action="active-order">Ver pedido em andamento</button>`);return;}draft={service};const delivery=['delivery','documents'].includes(service);showModal(delivery?'O que vamos entregar?':'Para onde vamos?',`<div class="notice info">Preencha com endereços fictícios. A rota e o preço serão simulados.</div><form id="request-form"><input type="hidden" name="service" value="${service}"><label class="field"><span>${delivery?'Local de retirada':'Sua origem'}</span><input name="from" required minlength="3" maxlength="100" value="Centro, Castanhal" autocomplete="off"></label><label class="field"><span>${delivery?'Endereço de entrega':'Seu destino'}</span><input name="to" required minlength="3" maxlength="100" placeholder="Ex.: Praça da Matriz, Castanhal" autocomplete="off"></label>${delivery?`<label class="field"><span>Tipo de entrega</span><select name="deliveryType">${deliveryTypes.map(x=>`<option ${service==='documents'&&x==='Documento'?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Observações de teste <span class="muted">(opcional)</span></span><textarea name="note" placeholder="Ex.: pacote pequeno, já embalado" maxlength="180" rows="2"></textarea></label>`:''}<label class="field"><span>Pagamento simulado</span><select name="payment"><option>Pix demo</option><option>Dinheiro demo</option><option>Carteira demo</option></select></label><div id="form-error" class="error" role="alert"></div><button class="primary full">Calcular estimativa</button></form>`);}
function quoteModal(){if(!draft)return;const q=quote(draft.service!,draft.from!,draft.to!);showModal('Confira seu pedido',`${mapView()}${routePoints(draft)}<div class="summary-line"><span class="muted">${q.distance} km · ${q.minutes} min estimados</span><strong>${serviceFor(draft.service!).name}</strong></div><div class="summary-line"><span class="muted">Pagamento simulado</span><strong>${esc(draft.payment)}</strong></div><div class="summary-line total"><span>Total demo</span><span>${money(q.price)}</span></div><div class="notice">Simulação sem contratação ou cobrança. Nenhuma pessoa será acionada.</div><div id="form-error" class="error" role="alert"></div><div class="actions"><button class="secondary" data-action="edit-request">Editar</button><button class="primary" data-action="confirm-request">Confirmar pedido demo</button></div>`);}
function ratingModal(id:string){const o=state.orders.find(o=>o.id===id)!;ratingValue=o.rating||0;ratingTags=o.tags||[];showModal('Como foi sua experiência?',`<p class="muted small" style="text-align:center">${o.id} · ${esc(o.food?.courierName||professionals[o.professional!]?.name||'Profissional Demo')}</p><div class="stars-select" aria-label="Avaliação de 1 a 5">${[1,2,3,4,5].map(n=>`<button aria-label="${n} estrelas" data-action="star" data-value="${n}" class="${n<=ratingValue?'selected':''}">★</button>`).join('')}</div><div class="tags">${(featureFlags.deliveryFocus?['Gentil','Pontual','Pedido bem cuidado','Boa entrega']:['Gentil','Pontual','Viagem tranquila','Cuidado com o pacote']).map(t=>`<button class="${ratingTags.includes(t)?'selected':''}" data-action="tag" data-value="${t}">${t}</button>`).join('')}</div><div id="form-error" class="error" role="alert"></div><button class="primary full" data-action="save-rating" data-id="${id}">Salvar avaliação demo</button>`);}
function addressesModal(){showModal('Seus lugares',`<p class="muted small">Endereços fictícios para a demonstração.</p>${state.addresses.map(a=>`<div class="transaction">${icon(a.label==='Casa'?'home':'pin')}<div><strong>${esc(a.label)}</strong><p>${esc(a.address)}</p></div></div>`).join('')}<form id="address-form"><div class="form-grid"><label class="field"><span>Nome do local</span><input name="label" placeholder="Ex.: Academia" required maxlength="30"></label><label class="field"><span>Endereço fictício</span><input name="address" placeholder="Rua de Exemplo, 100" required maxlength="100"></label></div><button class="primary full">Salvar endereço demo</button></form>`);}
function handleAction(button:HTMLButtonElement){const a=button.dataset.action,id=button.dataset.id!,v=button.dataset.value!;try{
if(featureFlags.deliveryFocus&&a==='request'){if(button.dataset.service==='food')go('food','client');else toast('Este serviço está oculto nesta etapa.');return;}if(featureFlags.deliveryFocus&&a==='apply'){go('profile');return;}if(featureFlags.deliveryFocus&&a==='help'){focusedHelpModal();return;}if(featureFlags.deliveryFocus&&a==='soon'){beerComingSoon();return;}if(featureFlags.deliveryFocus&&a==='admin'&&!focusAdminTabs().some(t=>t[0]===v)){adminView='dashboard';render();return;}
if(a?.startsWith('food-')){handleFoodAction(button);return;}
if(a==='role'){const requested=button.dataset.role as Role;if(!roleVisible(requested)){go('home','client');return;}state.role=requested;tabFilter='all';adminView='dashboard';save();go('home');if(currentRoute().role===state.role)render();}
else if(a==='home')go();else if(a==='profile')go('profile');else if(a==='close')modal.close();else if(a==='order')go('order',state.role,id);else if(a==='filter'){tabFilter=v;render();}else if(a==='admin'){adminView=v;render();}else if(a==='request')requestModal(button.dataset.service as ServiceId);
else if(a==='soon'){const s=serviceFor(button.dataset.service!);showModal(`${s.name} está chegando`,`<p class="muted">A compra em lojas será uma próxima etapa do TitoJá. Hoje você pode testar a entrega de itens já comprados, escolhendo o tipo ${s.name.toLowerCase()}.</p><button class="primary full" data-action="request" data-service="delivery">Testar uma entrega</button>`);}
else if(a==='confirm-request'){if(!draft)return;const o=createOrder(state,draft as OrderInput);draft=null;save();modal.close();go('order','client',o.id);toast('Pedido demo criado!');}
else if(a==='edit-request'){const old={...draft};requestModal(old.service!);for(const [k,val]of Object.entries(old)){const f=modal.querySelector<HTMLInputElement>(`[name="${k}"]`);if(f)f.value=val||'';}draft=old;}
else if(a==='active-order'){const o=state.orders.find(o=>!['completed','cancelled'].includes(o.status));if(o)go('order','client',o.id);}
else if(a==='online'){state.online[state.role as ProfessionalRole]=!state.online[state.role as ProfessionalRole];save();render();}
else if(a==='accept'){acceptOrder(state,id,state.role as ProfessionalRole);save();go('order',state.role,id);toast('Pedido aceito na demonstração');}
else if(a==='reject'){const o=state.orders.find(o=>o.id===id)!;if(o.status!=='searching')return;o.rejectedBy=[...new Set([...(o.rejectedBy||[]),state.role as ProfessionalRole])];save();render();toast('Pedido recusado. Ele continua aguardando um profissional.');}
else if(a==='restore-queue'){visibleOrders(state).forEach(o=>{if(o.status==='searching'||o.status==='ready')o.rejectedBy=[];});save();render();toast('Fila de demonstração atualizada');}
else if(a==='advance'){const o=state.orders.find(o=>o.id===id)!;if(o.status==='ongoing'){showModal(o.kind==='ride'?'Finalizar corrida?':'Confirmar entrega?',`<p class="muted">${o.kind==='ride'?'Confirme a chegada ao destino na simulação.':'O código fictício de confirmação é 1234.'}</p>${o.kind==='delivery'?`<form id="delivery-confirm"><input type="hidden" name="id" value="${id}"><label class="field"><span>Código de teste</span><input name="code" inputmode="numeric" pattern="1234" maxlength="4" placeholder="1234" required autocomplete="off"></label><small class="muted">Use 1234. Nenhum código real será enviado.</small><button class="primary full">Confirmar entrega demo</button></form>`:`<button class="primary full" data-action="finish" data-id="${id}">Finalizar corrida demo</button>`}`);}else{advanceOrder(state,id,state.role as ProfessionalRole);save();render();toast('Etapa atualizada');}}
else if(a==='finish'){advanceOrder(state,id,state.role as ProfessionalRole);save();modal.close();render();toast('Pedido finalizado! Volte ao perfil Cliente para avaliar.');}
else if(a==='cancel')showModal('Cancelar pedido?',`<p class="muted">O pedido será encerrado na demonstração. Não há multa ou cobrança real.</p><div class="actions"><button class="secondary" data-action="close">Manter pedido</button><button class="primary" data-action="confirm-cancel" data-id="${id}">Cancelar pedido demo</button></div>`);
else if(a==='confirm-cancel'){cancelOrder(state,id);save();modal.close();render();toast('Pedido cancelado');}
else if(a==='rating')ratingModal(id);else if(a==='star'){ratingValue=Number(v);modal.querySelectorAll<HTMLButtonElement>('[data-action="star"]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.value)<=ratingValue));}else if(a==='tag'){ratingTags=ratingTags.includes(v)?ratingTags.filter(t=>t!==v):[...ratingTags,v];button.classList.toggle('selected',ratingTags.includes(v));}
else if(a==='save-rating'){rateOrder(state,id,ratingValue,ratingTags);save();modal.close();render();toast('Sua avaliação demo foi salva. Obrigado!');}
else if(a==='notifications'){visibleNotifications(state).forEach(n=>n.read=true);save();render();showModal('Notificações',state.settings.notifications?visibleNotifications(state).map(n=>`<div class="notification">${icon('bell')}<span>${esc(n.text)}</span></div>`).join(''):'<p class="muted">As notificações estão desativadas nas configurações da demo.</p>');}
else if(a==='addresses')addressesModal();else if(a==='apply')go('apply');else if(a==='help')showModal('Estamos juntos nesse teste',`<div class="notice info">TitoJá · Protótipo frontend</div><p style="margin-top:18px">Comida: escolha os lanches e confirme o pagamento fictício como Cliente. No Restaurante, aceite, prepare e marque como pronto. Só então o Entregador poderá aceitar, retirar e entregar.</p><p style="margin-top:18px">1. Crie uma corrida ou entrega como Cliente.</p><p style="margin-top:10px">2. Troque para Motorista ou Entregador, fique online e aceite.</p><p style="margin-top:10px">3. Avance as etapas e volte ao Cliente para avaliar.</p><div class="divider"></div><p class="small muted">Os pedidos são guardados só neste navegador. Mapas, dinheiro, cadastros, notificações e profissionais são simulados. Não há atendimento real nesta tela.</p><button class="primary full" data-action="close">Entendi</button>`);
else if(a==='share')showModal('Compartilhar pedido · demo',`<div class="notice">Nenhuma mensagem será enviada e ninguém receberá sua localização.</div><p style="margin-top:18px">Exemplo de mensagem:</p><div class="card" style="margin-top:12px;padding:15px"><p class="small">Estou testando o pedido fictício ${esc(id)} no TitoJá. Este acompanhamento é uma simulação, sem rastreamento real.</p></div><button class="primary full" data-action="close">Fechar demonstração</button>`);
else if(a==='sos')showModal('SOS · demonstração',`<div class="notice">Esta tela NÃO aciona emergência, polícia, atendimento ou contatos. Não use este protótipo para pedir socorro.</div><p style="margin-top:18px">Em uma emergência real no Brasil, use seu telefone para ligar 190 (polícia) ou 192 (SAMU).</p><button class="primary full" data-action="close">Entendi, fechar</button>`);
else if(a==='topup')showModal('Saldo de teste',`<p class="muted">Adicione R$ 50,00 fictícios à sua carteira. Não há cobrança, cartão ou Pix envolvido.</p><button class="primary full" data-action="confirm-topup">Adicionar R$ 50,00 demo</button>`);
else if(a==='confirm-topup'){state.balance+=50;state.transactions.unshift({id:'t'+Date.now(),label:'Crédito de teste',amount:50,date:new Date().toISOString()});save();modal.close();render();toast('R$ 50,00 fictícios adicionados');}
else if(a==='withdraw')showModal('Saque · demonstração',`<div class="notice">Não há dinheiro real nem dados bancários conectados.</div><p style="margin-top:18px">Na versão final, o profissional poderá solicitar o saque de valores disponíveis. Esta tela é somente uma prévia.</p><button class="primary full" data-action="close">Entendi</button>`);
else if(a==='edit-profile')showModal('Editar perfil fictício',`<form id="profile-form"><label class="field"><span>Nome de teste</span><input name="name" value="${esc(state.name)}" required maxlength="30"></label><div class="notice">Não inclua dados pessoais reais.</div><button class="primary full">Salvar perfil</button></form>`);
else if(a==='logout'){state.loggedIn=false;save();go('home');render();}else if(a==='signup')showModal('Criar perfil fictício',`<form id="signup-form"><label class="field"><span>Nome fictício</span><input name="name" value="Cliente Demo" required maxlength="30"></label><div class="notice">Não cria uma conta real, não pede senha e não envia dados.</div><button class="primary full">Criar e explorar</button></form>`);
else if(a==='application'){const application=state.applications.find(x=>x.id===id)!;if(application.status!=='pending')return;application.status=v as 'approved'|'rejected';notify(state,application.name+': cadastro '+(v==='approved'?'aprovado':'reprovado')+' na demonstração.');save();render();toast('Cadastro revisado na demo');}
else if(a==='coupon'){const coupon=state.coupons.find(c=>c.id===id)!;coupon.active=!coupon.active;save();render();}else if(a==='review-payments'){state.paymentsReviewed=true;save();render();toast('Conferência demo registrada');}else if(a==='resolve'){state.complaints.find(c=>c.id===id)!.status='resolved';save();render();}else if(a==='setting'){state.settings.notifications=!state.settings.notifications;save();render();}
else if(a==='reset')showModal('Restaurar demonstração?',`<p class="muted">Seus pedidos, avaliações, saldo e cadastros de teste serão substituídos pelos exemplos iniciais.</p><div class="actions"><button class="secondary" data-action="close">Manter dados</button><button class="primary" data-action="confirm-reset">Restaurar demo</button></div>`);
else if(a==='confirm-reset'){state=initialState();save();modal.close();go('home','client');render();toast('Demonstração restaurada');}
else if(a==='export'){const rows=[['Pedido','Serviço','Origem','Destino','Estado','Total fictício'],...visibleOrders(state).map(o=>[o.id,serviceFor(o.service).name,o.from,o.to,statusLabel(o),o.price])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='titoja-relatorio-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Relatório de teste gerado');}
}catch(e){const error=modal.querySelector('#form-error');if(error)error.textContent=e.message;else toast(e.message);}}
document.addEventListener('click',e=>{const button=(e.target as Element).closest<HTMLButtonElement>('[data-action]');if(button&&!button.disabled)handleAction(button);});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target as HTMLFormElement;const data=Object.fromEntries(new FormData(form)) as Record<string,string>;try{if(form.id==='food-checkout-form'){const order=createFoodOrder(state,data.to,data.note||'',data.paymentApproved==='yes');notify(state,order.id+': pedido de comida enviado ao restaurante.');save();go('order','client',order.id);render();toast('Pagamento fictício OK. Pedido enviado ao restaurante!');}else if(form.id==='food-register-form'){registerDemoProfile(state,data.role as FoodRole,data.name);save();modal.close();render();toast('Cadastro fictício salvo neste navegador');}else if(form.id==='request-form'){if(featureFlags.deliveryFocus)throw Error('Este serviço está oculto nesta etapa.');if(data.from.trim().toLowerCase()===data.to.trim().toLowerCase())throw Error('Escolha um destino diferente da origem');draft={...data,service:data.service as ServiceId};quoteModal();}else if(['login-form','signup-form','profile-form'].includes(form.id)){if(!data.name.trim())throw Error('Informe um nome fictício');state.name=data.name.trim();state.loggedIn=true;save();modal.close();render();toast('Tudo pronto para explorar');}else if(form.id==='address-form'){state.addresses.push({label:data.label.trim(),address:data.address.trim()});save();addressesModal();toast('Endereço fictício salvo');}else if(form.id==='application-form'){if(state.applications.some(a=>a.id==='my-demo'))return;state.applications.push({id:'my-demo',name:data.name.trim(),type:data.type,vehicle:data.vehicle.trim(),status:'pending'});notify(state,'Novo cadastro profissional aguardando análise demo.');save();render();toast('Cadastro de teste enviado para análise');}else if(form.id==='delivery-confirm'){if(data.code!=='1234')throw Error('Use o código fictício 1234');advanceOrder(state,data.id,state.role as ProfessionalRole);save();modal.close();render();toast('Entrega finalizada na demonstração');}}catch(err){const el=form.querySelector('#form-error');if(el)el.textContent=err.message;else toast(err.message);}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});modal.addEventListener('close',()=>{if(modalFocus instanceof HTMLElement)modalFocus.focus();});window.addEventListener('hashchange',()=>{modal.close();render();window.scrollTo({top:0,behavior:'instant'});});window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){try{state=normalizeFoodState(JSON.parse(e.newValue||'null')||initialState());render(false);}catch{}}});
interface DemoTool { name:string; title:string; description:string; inputSchema:object; annotations:{readOnlyHint:boolean;untrustedContentHint:boolean}; execute:(input:unknown)=>unknown }
declare global { interface Document { modelContext?:{registerTool:(tool:DemoTool,options:{signal:AbortSignal})=>unknown} } }
function isRoleInput(input:unknown):input is {role:Role}{return typeof input==='object'&&input!==null&&'role' in input&&roleVisible(String(input.role) as Role);}
render();
if(document.modelContext?.registerTool){const abort=new AbortController();const register=(t:DemoTool)=>{try{Promise.resolve(document.modelContext!.registerTool(t,{signal:abort.signal})).catch(()=>{});}catch{}};register({name:'titoja_read_demo_orders',title:'Ler pedidos de teste',description:'Retorna os pedidos fictícios deste navegador. Não acessa serviços reais.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({orders:visibleOrders(state).map(({id,status,service,from,to,price})=>({id,status,service,from,to,price}))})});register({name:'titoja_switch_demo_role',title:'Alternar perfil de teste',description:'Navega entre os perfis habilitados da demonstração. Não altera pedidos.',inputSchema:{type:'object',properties:{role:{type:'string',enum:enabledRoles()}},required:['role'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:(input:unknown)=>{if(!isRoleInput(input))throw Error('Perfil inválido');state.role=input.role;save();go('home');render();return {role:state.role};}});window.addEventListener('pagehide',()=>abort.abort(),{once:true});}

function demoIdentityBar(){
 const role=state.role as FoodRole,p=state.demoProfiles[role];
 return `<div class="demo-identity"><span>${icon('lab')} <span>${p?`<strong>${esc(p.name)}</strong> · ${role==='restaurant'?restaurant.name:role==='courier'?'entregador fictício':'cliente fictício'}`:'Perfil de demonstração'}<small>Mesmo navegador · cadastros e pagamentos simulados</small></span></span>${p?`<button class="text-button" data-action="food-register">${p.registered?'Editar cadastro':'Testar cadastro'}</button>`:''}</div>`;
}
function foodPhoto(extra=''){return `<div class="food-photo ${extra}">${art(serviceFor('food'))}</div>`;}
function foodPage(){
 return `<div class="content-page food-page">${head('Comida','Um restaurante fictício para testar do pedido à entrega')}<button class="restaurant-card" data-action="food-menu">${foodPhoto()}<div><span class="food-kicker">ABERTO NA DEMO</span><h2>${restaurant.name}</h2><p>${restaurant.description}</p><div class="restaurant-meta"><span>★ 4,9 · fictício</span><span>25–35 min · estimativa</span></div><div class="food-delivery">Entrega ilustrativa ${money(restaurant.deliveryFee)}</div></div>${icon('chevron')}</button><div class="notice info">Escolha seus lanches. Depois, alterne entre Restaurante e Entregador no topo para testar cada etapa. Os dados ficam só neste navegador.</div>${state.foodCart.length?`<button class="primary full" data-action="food-cart" style="margin-top:18px">Ver sacola · ${state.foodCart.reduce((s,l)=>s+l.quantity,0)} itens</button>`:''}</div>`;
}
function foodMenuPage(){
 if(state.role!=='client')return empty('Abra o perfil Cliente','O cardápio e a sacola pertencem ao cliente fictício.');
 const count=state.foodCart.reduce((s,l)=>s+l.quantity,0);
 return `<div class="content-page food-page">${head(restaurant.name,'Cardápio fictício · entrega ilustrativa R$ 8,00')}<div class="menu-banner">${foodPhoto()}<div><span class="food-kicker">FEITO NA HORA, NA DEMO</span><h2>Seu lanche favorito,<br>do seu jeito.</h2><p>25–35 min · 1 restaurante de teste</p></div></div>${['Lanches','Acompanhamentos','Bebidas'].map(category=>`<section class="menu-section"><h2>${category}</h2><div class="menu-grid">${menu.filter(p=>p.category===category).map(p=>{const qty=state.foodCart.find(l=>l.productId===p.id)?.quantity||0;return `<article class="menu-product"><div class="menu-copy"><h3>${p.name}</h3><p>${p.description}</p><strong>${money(p.price)}</strong></div><div class="product-side">${p.visual==='burger'?foodPhoto('product-photo'):`<span class="product-category-icon">${icon(p.category==='Bebidas'?'box':'orders')}</span>`}<button class="add-product" data-action="food-add" data-id="${p.id}" aria-label="Adicionar ${p.name}">${icon('plus')}${qty?`<span>${qty}</span>`:''}</button></div></article>`;}).join('')}</div></section>`).join('')}<div class="food-cart-bar"><span><strong>${count?`${count} ${count===1?'item':'itens'} na sacola`:'Sua sacola está vazia'}</strong><small>${count?money(cartSubtotal(state))+' em produtos':'Adicione um lanche para começar'}</small></span><button class="primary" data-action="food-cart" ${count?'':'disabled'}>Ver sacola</button></div></div>`;
}
function quantityControl(id:string,quantity:number,name:string){return `<div class="quantity-control"><button data-action="food-minus" data-id="${id}" aria-label="Diminuir ${esc(name)}">−</button><strong aria-label="Quantidade">${quantity}</strong><button data-action="food-add" data-id="${id}" ${quantity>=20?'disabled':''} aria-label="Aumentar ${esc(name)}">+</button></div>`;}
function foodTotals(subtotal:number,fee=restaurant.deliveryFee){return `<div class="food-totals"><div class="summary-line"><span>Produtos</span><strong>${money(subtotal)}</strong></div><div class="summary-line"><span>Frete ilustrativo</span><strong>${money(fee)}</strong></div><div class="summary-line total"><span>Total simulado</span><span>${money(subtotal+fee)}</span></div></div>`;}
function foodCartPage(){
 const items=cartItems(state);if(state.role!=='client')return empty('Sacola do cliente','Troque para o perfil Cliente para continuar.');
 if(!items.length)return `<div class="content-page food-page">${head('Sua sacola')}<div class="card empty">${icon('box')}<h3>Um lanche cai bem, né?</h3><p>Sua sacola está vazia. Escolha algo no cardápio.</p><button class="primary" data-action="food-menu">Ver cardápio</button></div></div>`;
 return `<div class="content-page food-page">${head('Sua sacola',restaurant.name)}<div class="card">${items.map(item=>`<div class="cart-item"><div class="grow"><h3>${esc(item.name)}</h3><p>${money(item.unitPrice)} cada</p><button class="text-button" data-action="food-remove" data-id="${item.productId}">Remover</button></div><div class="cart-item-right"><strong>${money(item.lineTotal)}</strong>${quantityControl(item.productId,item.quantity,item.name)}</div></div>`).join('')}<button class="text-button" data-action="food-menu">Adicionar mais produtos</button><div class="divider"></div>${foodTotals(cartSubtotal(state))}<button class="primary full" data-action="food-checkout">Continuar para pagamento demo</button><p class="small muted food-footnote">Valores fictícios. Nenhuma contratação ou cobrança.</p></div></div>`;
}
function foodCheckoutPage(){
 if(state.role!=='client'||!state.foodCart.length)return foodCartPage();
 const active=visibleOrders(state).find(o=>!['completed','cancelled'].includes(o.status));
 if(active)return `<div class="content-page food-page">${head('Um pedido de cada vez')}<div class="card"><h3>Você já tem um pedido em andamento</h3><p class="muted food-footnote">Sua sacola está salva. Finalize ou cancele o pedido atual para continuar.</p><button class="primary full" data-action="order" data-id="${active.id}">Ver pedido atual</button></div></div>`;
 return `<div class="content-page food-page">${head('Finalizar pedido','Pagamento 100% fictício')}<div class="checkout-layout"><form id="food-checkout-form" class="card"><h3>Entrega para ${esc(state.demoProfiles.client.name)}</h3><label class="field"><span>Endereço fictício de entrega</span><input name="to" value="Rua Exemplo, 120 · Centro, Castanhal" required minlength="5" maxlength="100" autocomplete="off"></label><label class="field"><span>Observações de teste (opcional)</span><textarea name="note" rows="2" maxlength="180" placeholder="Ex.: sem cebola; chamar no portão fictício"></textarea></label><div class="payment-demo"><span class="payment-symbol">${icon('shield')}</span><div><strong>Pagamento de demonstração</strong><p>Nenhum Pix, cartão ou gateway conectado</p></div></div><label class="payment-check"><input name="paymentApproved" type="checkbox" value="yes" required><span>Simular pagamento aprovado. Sei que não há cobrança real.</span></label><div id="form-error" class="error" role="alert"></div><button class="primary full">Pagamento OK · enviar pedido demo</button><button type="button" class="text-button full" data-action="food-cart">Voltar à sacola</button></form><aside class="card checkout-summary"><h3>${restaurant.name}</h3>${cartItems(state).map(i=>`<div class="summary-line"><span>${i.quantity}× ${esc(i.name)}</span><strong>${money(i.lineTotal)}</strong></div>`).join('')}<div class="divider"></div>${foodTotals(cartSubtotal(state))}<p class="small muted">O restaurante recebe o pedido após a confirmação. O entregador só recebe a oferta quando ele estiver pronto.</p></aside></div></div>`;
}
function foodActionButton(o:Order,action:FoodAction,secondary=false){return `<button class="${secondary?'secondary':'primary'} full" data-action="food-transition" data-id="${o.id}" data-food-action="${action}" data-expected="${o.status}">${foodActionLabels[action]}</button>`;}
function foodOrderItems(o:Order){return o.food!.items.map(item=>`<div class="food-order-line"><span class="item-qty">${item.quantity}×</span><div class="grow"><strong>${esc(item.name)}</strong><small>${money(item.unitPrice)} cada</small></div><strong>${money(item.lineTotal)}</strong></div>`).join('');}
function foodNextAction(o:Order):FoodAction|undefined {
 if(state.role==='restaurant')return ({pendingAcceptance:'restaurantAccept',restaurantAccepted:'startPreparing',preparing:'markReady'} as Record<string,FoodAction>)[o.status];
 if(state.role==='courier')return ({ready:'courierAccept',assigned:'goPickup',pickingUp:'confirmPickup',foodCollected:'startDelivery',outForDelivery:'deliver'} as Record<string,FoodAction>)[o.status];
}
function trackingArtwork(o:Order,scene:string){
 const scooter=['pickup','moving'].includes(scene);
 return `<div class="tracking-scene scene-${scene}" aria-hidden="true"><div class="scene-halo halo-one"></div><div class="scene-halo halo-two"></div><div class="scene-disc"></div><div class="tracking-illustration">${scooter?'<img src="./assets/delivery-scooter.png" alt="" decoding="async">':scene==='ready'?art(services[2]):foodPhoto()}</div><span class="scene-state-badge">${icon(trackingView(o.status,state.role).icon)}</span>${scene==='moving'?`<div class="scene-route"><span>${icon('box')}</span><i><b></b></i><span>${icon('home')}</span></div>`:''}<span class="scene-spark spark-one"></span><span class="scene-spark spark-two"></span></div>`;
}
function trackingProgress(o:Order){const view=trackingView(o.status,state.role);return `<ol class="tracking-progress" aria-label="Progresso do pedido">${trackingStages.map((stage,i)=>`<li class="${i<view.stage||o.status==='completed'?'done':''} ${i===view.stage?'current':''}" ${i===view.stage?'aria-current="step"':''}><span class="progress-segment"></span><span class="progress-stage-icon">${icon(i<view.stage||o.status==='completed'?'check':stage.icon)}</span><span>${stage.label}</span></li>`).join('')}</ol>`;}
function trackingPanel(o:Order,compact=false){
 const view=trackingView(o.status,state.role),f=o.food!,last=f.history.at(-1)!,time=new Date(last.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}),done=['completed','cancelled'].includes(o.status);
 return `<section class="tracking-panel ${compact?'compact':''} track-${view.scene}" data-tracking-status="${o.status}"><div class="tracking-panel-top"><span class="tracking-live ${done?'settled':''}"><i></i>${o.status==='completed'?'Pedido concluído':o.status==='cancelled'?'Pedido encerrado':'Acompanhamento demo'}</span><span class="tracking-order-id">${o.id}</span></div><div class="tracking-hero">${trackingArtwork(o,view.scene)}<div class="tracking-hero-copy" role="status" aria-live="polite" aria-atomic="true"><span class="food-kicker">${esc(f.restaurantName)}</span><h2>${view.title}</h2><p>${view.description}</p></div></div>${o.status==='cancelled'?'':trackingProgress(o)}<div class="tracking-panel-foot"><span>${icon('clock')}Atualizado às ${time}</span><span>${icon(f.paymentStatus==='approved'?'shield':'close')}Pagamento ${f.paymentStatus==='approved'?'demo OK':'cancelado'}</span></div></section>`;
}
function trackingNext(o:Order){
 const next=foodNextAction(o),view=trackingView(o.status,state.role),done=['completed','cancelled'].includes(o.status),handoff=['pendingAcceptance','restaurantAccepted','preparing'].includes(o.status)?'restaurant':o.status==='completed'?'client':'courier';
 return `<div class="tracking-next ${done?'tracking-done':''}"><div class="tracking-next-heading"><span>${icon(o.status==='cancelled'?'close':done?'check':next?'check':'clock')}</span><div><small>${o.status==='cancelled'?'PEDIDO ENCERRADO':done?'TUDO CERTO POR AQUI':next?'SUA PRÓXIMA AÇÃO':'PRÓXIMA ETAPA'}</small><strong>${view.next}</strong></div></div>${next?foodActionButton(o,next):''}${state.role==='client'&&o.status==='completed'?`<button class="primary full" data-action="rating" data-id="${o.id}">${o.rating?'★ '+o.rating+' · Ver sua avaliação':'Avaliar experiência'}</button>`:''}${!done&&!next?`<div class="tracking-test-handoff"><span>Para continuar o teste manual:</span><button class="text-button" data-action="role" data-role="${handoff}">Abrir ${handoff==='restaurant'?'Restaurante':'Entregador'}</button></div>`:''}${state.role!=='client'?'<button class="text-button full tracking-client-link" data-action="role" data-role="client">Acompanhar como Cliente</button>':''}</div>`;
}
function trackingCourier(o:Order){const f=o.food!;if(o.status==='cancelled')return '';if(!f.courierName)return `<div class="tracking-courier unassigned"><span class="courier-avatar">${icon('bike')}</span><div><strong>${o.status==='ready'?'Aguardando um entregador':'Sua entrega vem depois do preparo'}</strong><p>${o.status==='ready'?'A oferta está disponível no perfil Entregador.':'O entregador só recebe a oferta quando estiver pronto.'}</p></div></div>`;return `<div class="tracking-courier"><span class="courier-avatar">${esc(f.courierName.split(' ').map(w=>w[0]).slice(0,2).join(''))}</span><div class="grow"><small>SEU ENTREGADOR FICTÍCIO</small><strong>${esc(f.courierName)}</strong><p>Honda Biz · DEMO-002</p></div><span class="courier-rating">★ 4,9<small>demo</small></span></div>`;}
function trackingHistory(o:Order){return `<details class="tracking-history"><summary><span>${icon('orders')}Ver atualizações do pedido</span>${icon('down')}</summary><div class="food-timeline">${o.food!.history.map(e=>`<div class="food-step done"><span>${icon(e.status==='cancelled'?'close':'check')}</span><div><strong>${foodStatusLabel(e.status)}</strong><small>${new Date(e.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})} · ${({client:'Cliente',restaurant:'Restaurante',courier:'Entregador',driver:'Motorista',admin:'Admin'})[e.by]}</small></div></div>`).join('')}</div></details>`;}
function foodWorkCard(o:Order){return `<article class="food-work-card">${trackingPanel(o,true)}${trackingNext(o)}<div class="work-order-brief"><span>${o.food!.items.reduce((n,i)=>n+i.quantity,0)} itens · ${esc(o.food!.restaurantName)}</span><button class="text-button" data-action="order" data-id="${o.id}">Detalhes do pedido</button></div></article>`;}
function foodOrderPage(o:Order){
 const f=o.food!,done=['completed','cancelled'].includes(o.status);
 return `<div class="content-page food-page food-tracking-page">${head(state.role==='client'?'Acompanhe seu pedido':state.role==='restaurant'?'Da cozinha para o cliente':'Sua entrega, etapa por etapa',`${f.restaurantName} · ${o.id}`)}<div class="tracking-layout rich-tracking-layout"><div class="stack">${trackingPanel(o)}${trackingNext(o)}${trackingCourier(o)}${trackingHistory(o)}<p class="tracking-demo-caption">${icon('lab')}Etapas atualizadas manualmente neste navegador. Animação ilustrativa, sem GPS ou previsão de chegada real.</p></div><aside class="stack"><div class="card food-receipt"><div class="receipt-heading">${foodPhoto()}<div><span class="food-kicker">SEU PEDIDO</span><h3>${f.restaurantName}</h3><p>${o.id} · ${date(o.created)}</p></div></div><p class="receipt-customer">${icon('user')}${esc(f.customerName)} · cliente fictício</p>${foodOrderItems(o)}${o.note?`<div class="notice food-footnote"><strong>Observação</strong><br>${esc(o.note)}</div>`:''}<div class="divider"></div>${foodTotals(f.subtotal,f.deliveryFee)}<div class="payment-state ${f.paymentStatus==='approved'?'approved':''}">${icon(f.paymentStatus==='approved'?'check':'close')}Pagamento fictício ${f.paymentStatus==='approved'?'aprovado':'cancelado'}</div></div><div class="card tracking-destination"><h3>${state.role==='courier'?'Seu percurso de teste':'Retirada e entrega'}</h3>${routePoints(o)}<p class="small muted">Endereços fictícios · sem mapa ou rastreamento real</p></div>${o.status==='pendingAcceptance'&&['client','restaurant'].includes(state.role)?`<button class="text-button tracking-cancel" data-action="food-cancel" data-id="${o.id}">${state.role==='client'?'Cancelar pedido':'Recusar pedido'}</button>`:''}${done&&state.role==='client'?'<button class="secondary full" data-action="food-menu">Voltar ao cardápio</button>':''}<p class="small muted">Frete ilustrativo; comissão comercial não definida. Nenhuma cobrança real.</p></aside></div></div>`;
}
function restaurantPage(){
 const orders=state.orders.filter(o=>o.food),active=orders.filter(o=>!['completed','cancelled'].includes(o.status)),waiting=active.filter(o=>o.status==='pendingAcceptance');
 return `<div class="content-page food-page restaurant-workspace">${head('Sua cozinha em movimento',restaurant.name,false)}<div class="restaurant-dashboard-head">${foodPhoto()}<div><span class="food-kicker">PAINEL DO RESTAURANTE</span><h2>Olá, ${esc(state.demoProfiles.restaurant.name)}</h2><p>${waiting.length?'Tem pedido novo esperando por você.':active.length?'Cada etapa deixa o cliente por dentro.':'Tudo pronto para o próximo pedido.'}</p></div><span class="kitchen-status"><i></i>Cozinha demo</span></div><div class="kitchen-stats"><div><span>Novos</span><strong>${waiting.length}</strong></div><div><span>Em andamento</span><strong>${active.length}</strong></div><div><span>Entregues</span><strong>${orders.filter(o=>o.status==='completed').length}</strong></div></div><div class="section-title"><h2>${waiting.length?'Pedido novo':'Na sua cozinha'}</h2><span class="demo-pill">${active.length} ativo${active.length===1?'':'s'}</span></div>${!active.length?`<div class="card empty restaurant-empty">${foodPhoto()}<h3>A cozinha está pronta</h3><p>O próximo pedido aparece aqui com os itens, a observação e o pagamento de teste.</p><button class="primary" data-action="role" data-role="client">Criar pedido como Cliente</button></div>`:`<div class="stack">${active.map(o=>`<article class="restaurant-order food-work-card">${trackingPanel(o,true)}<div class="kitchen-ticket"><div class="row between"><h3>${o.id} · ${esc(o.food!.customerName)}</h3><span class="ticket-count">${o.food!.items.reduce((sum,i)=>sum+i.quantity,0)} itens</span></div>${foodOrderItems(o)}${o.note?`<div class="notice food-footnote"><strong>Observação do cliente</strong><br>${esc(o.note)}</div>`:''}<div class="summary-line total"><span>Total demo</span><span>${money(o.price)}</span></div></div>${trackingNext(o)}<div class="work-order-brief"><span>Pagamento fictício OK</span><button class="text-button" data-action="order" data-id="${o.id}">Ver detalhes</button></div></article>`).join('')}</div>`}<p class="tracking-demo-caption">${icon('lab')}A oferta do entregador só aparece depois de “Marcar como pronto”. Cada ação atualiza o mesmo pedido do cliente.</p>${orders.some(o=>['completed','cancelled'].includes(o.status))?`<div class="section-title" style="margin-top:26px"><h2>Histórico da cozinha</h2></div><div class="stack">${orders.filter(o=>['completed','cancelled'].includes(o.status)).slice(0,5).map(orderCard).join('')}</div>`:''}</div>`;
}
function foodOfferCard(o:Order){return `<article class="food-offer food-work-card">${trackingPanel(o,true)}<div class="courier-offer-body"><div class="courier-offer-value"><div><span>Frete ilustrativo</span><strong>${money(o.food!.deliveryFee)}</strong></div><span class="offer-ready-pill">${icon('check')}Pronto para retirar</span></div>${routePoints(o)}<div class="offer-items">${icon('box')}${o.food!.items.reduce((sum,i)=>sum+i.quantity,0)} itens · pagamento fictício aprovado</div>${foodActionButton(o,'courierAccept')}<button class="text-button full" data-action="order" data-id="${o.id}">Conferir detalhes do pedido</button></div></article>`;}
function restaurantWalletPage(){return `<div class="content-page food-page">${head('Vendas do restaurante','Valores inteiramente fictícios')}<div class="wallet-hero"><p>Produtos de pedidos entregues · demo</p><h1>${money(earnings('restaurant'))}</h1></div><div class="notice">Sem comissão comercial definida e sem pagamento ou saque real. O frete ilustrativo de R$ 8,00 é separado dos produtos.</div><div class="stack food-footnote">${state.orders.filter(o=>o.food&&o.status==='completed').map(orderCard).join('')||empty('Nenhuma venda concluída','Conclua o fluxo com o entregador para ver aqui.')}</div></div>`;}
function restaurantProfilePage(){return `<div class="content-page food-page">${head('Perfil do restaurante')}<div class="card"><div class="profile-hero"><div class="avatar">BT</div><div><h2>${esc(state.demoProfiles.restaurant.name)}</h2><p>${restaurant.name}</p></div></div><div class="divider"></div><p class="muted">Uma única loja fictícia, disponível para testar os pedidos deste navegador.</p><button class="primary full food-footnote" data-action="food-register">${state.demoProfiles.restaurant.registered?'Editar cadastro demo':'Criar cadastro demo'}</button><div class="notice food-footnote">Sem CNPJ, documentos, senha ou dados bancários reais.</div></div></div>`;}
function handleFoodAction(button:HTMLButtonElement){
 const a=button.dataset.action,id=button.dataset.id!;
 if(a==='food-open'){go('food','client');return;}if(a==='food-menu'){go('menu','client');return;}if(a==='food-cart'){go('cart','client');return;}if(a==='food-checkout'){go('checkout','client');return;}
 if(['food-add','food-minus','food-remove'].includes(a!)){const line=state.foodCart.find(l=>l.productId===id),qty=a==='food-remove'?0:(line?.quantity||0)+(a==='food-add'?1:-1);setCartQuantity(state,id,qty);save();render();if(a==='food-add')toast('Adicionado à sacola');return;}
 if(a==='food-register'){
   const role=(['client','restaurant','courier'].includes(state.role)?state.role:'client') as FoodRole;
   showModal('Cadastro de demonstração',`<form id="food-register-form"><input type="hidden" name="role" value="${role}"><div class="notice">Use apenas um nome inventado. Sem senha, documentos ou conta real.</div><label class="field"><span>${role==='restaurant'?'Responsável fictício pelo restaurante':'Nome fictício'}</span><input name="name" value="${esc(state.demoProfiles[role].name)}" required minlength="2" maxlength="40" autocomplete="off"></label>${role==='restaurant'?`<div class="summary-line"><span>Restaurante de teste</span><strong>${restaurant.name}</strong></div>`:''}<div id="form-error" class="error" role="alert"></div><button class="primary full">Salvar cadastro demo</button></form>`);return;
 }
 if(a==='food-cancel'){
   const o=state.orders.find(o=>o.id===id)!;showModal('Cancelar pedido fictício?',`<p>O restaurante ainda não aceitou. O pedido e o pagamento de teste serão cancelados, sem movimentar dinheiro.</p><div class="actions"><button class="secondary" data-action="close">Manter pedido</button>${foodActionButton(o,state.role==='restaurant'?'restaurantReject':'cancel')}</div>`);return;
 }
 if(a==='food-transition'){
   const action=button.dataset.foodAction as FoodAction;
   const o=transitionFood(state,id,action,button.dataset.expected as OrderStatus);notify(state,`${o.id}: ${foodStatusLabel(o.status)}`);save();modal.close();go('order',state.role,id);render();toast(foodStatusLabel(o.status));
 }
}

