function focusAdminTabs(){return [['dashboard','chart','Visão geral'],['users','users','Perfis demo'],['deliveries','box','Pedidos'],['finance','wallet','Resumo financeiro'],['payments','money','Pagamentos'],['ratings','star','Avaliações'],['reports','download','Relatórios'],['settings','settings','Configurações']];}
function deliveryHomePage(){
 const orders=visibleOrders(state),active=orders.find(o=>!['completed','cancelled'].includes(o.status)),count=state.foodCart.reduce((s,x)=>s+x.quantity,0);
 return `<div class="delivery-home"><section class="delivery-home-main"><div class="mobile-brand">${brand()}<button class="icon-button ${visibleNotifications(state).some(n=>!n.read)?'badge-dot':''}" data-action="notifications" aria-label="Notificações">${icon('bell')}</button></div><div class="delivery-welcome"><div><h1>Olá, ${esc(state.name)}!</h1><p>Seu pedido. Seu momento.</p></div><button class="icon-button" data-action="notifications" aria-label="Notificações">${icon('bell')}</button></div><button class="location" data-action="addresses">${icon('pin','location-pin')}<div class="grow"><span>Entregar em · endereço de teste</span><strong>Centro, Castanhal</strong></div>${icon('down')}</button>${active?`<div class="home-active-order"><div class="row between"><span class="food-kicker">SEU PEDIDO EM ANDAMENTO</span><span class="demo-pill">${active.id}</span></div><h2>${trackingView(active.status,'client').title}</h2><p>${active.food?.restaurantName||'Pedido de teste'}</p><button class="primary" data-action="order" data-id="${active.id}">Acompanhar pedido</button></div>`:''}<div class="section-title delivery-choice-title"><div><span class="food-kicker">TITOJÁ ENTREGA</span><h2>O que vai ser hoje?</h2></div></div><div class="delivery-choices">${enabledServices().map(id=>{const s=serviceFor(id),food=id==='food';return `<button class="delivery-choice ${food?'choice-food':'choice-beer'}" data-action="${food?'food-open':'soon'}" data-service="${id}"><span class="choice-pill ${food?'available':'coming'}">${food?'Teste disponível':'Em breve'}</span><div class="choice-art">${art(s)}</div><div class="choice-copy"><h2>${food?'Comida':'Entrega de cerveja'}</h2><p>${food?'Bateu a fome? Tem lanche caprichado.':'Sua gelada tem um lugar por aqui.'}</p><span class="choice-cta">${food?'Ver restaurantes':'Conhecer a novidade'}${icon(food?'orders':'clock')}</span></div></button>`}).join('')}</div>${count?`<button class="home-cart-resume" data-action="food-cart"><span class="home-cart-icon">${icon('box')}</span><span class="grow"><strong>Sua sacola está te esperando</strong><small>${count} ${count===1?'item':'itens'} · ${money(cartSubtotal(state))} em produtos</small></span>${icon('chevron')}</button>`:''}<div class="delivery-promise"><span>${icon('orders')}</span><div><strong>Do pedido até a sua porta</strong><p>Acompanhe cada etapa na demonstração.</p></div><span class="promise-mini-icons">${icon('clock')}${icon('bike')}${icon('check')}</span></div><div class="section-title delivery-recent-title"><h2>Seus pedidos</h2>${orders.length?'<a href="#/client/orders">Ver todos</a>':''}</div>${orders.length?`<div class="stack">${orders.slice(0,3).map(orderCard).join('')}</div>`:`<div class="delivery-empty-history"><span>${icon('orders')}</span><div><strong>Seu primeiro pedido começa aqui</strong><p>Escolha Comida para conhecer o cardápio.</p></div></div>`}<div class="mobile-only">${helpCard()}</div></section><aside class="delivery-home-aside"><div class="delivery-aside-art"><img src="./assets/delivery-scooter.png" alt="Scooter laranja de entrega, ilustração"><span>TITOJÁ · DEMONSTRAÇÃO</span><h2>Seu lanche,<br>um passo de cada vez.</h2><p>Peça, acompanhe o preparo e veja a entrega acontecer no teste.</p></div><div class="aside-box focus-demo-guide"><h3>Experimente os três lados</h3><div><b>1</b><span><strong>Cliente</strong><small>Escolha e confirme seu pedido</small></span></div><div><b>2</b><span><strong>Restaurante</strong><small>Aceite, prepare e deixe pronto</small></span></div><div><b>3</b><span><strong>Entregador</strong><small>Retire e conclua a entrega</small></span></div></div>${helpCard()}<p class="aside-note">Pedidos e cadastros fictícios, salvos neste navegador. Nenhuma cobrança ou entrega real.</p></aside></div>`;
}
