function focusedHelpModal(){showModal('Conheça a demonstração',`<div class="notice info">Comida já pode ser testada. Entrega de cerveja está em breve.</div><div class="focus-help-steps"><p><b>1. Cliente</b><br>Escolha Comida, adicione lanches e confirme o pagamento fictício.</p><p><b>2. Restaurante</b><br>Aceite o pedido, inicie o preparo e marque como pronto.</p><p><b>3. Entregador</b><br>Fique online, aceite a oferta, retire e confirme a entrega.</p></div><p class="small muted">Alterne os perfis no topo. Tudo fica neste navegador, sem conta, cobrança ou entrega real.</p><button class="primary full" data-action="close">Vamos testar</button>`);}
function deliveryCourierPage(){
 const p=state.demoProfiles.courier,orders=visibleOrders(state),active=orders.find(o=>o.professional==='courier'&&!['completed','cancelled'].includes(o.status)),queue=foodCourierQueue(state),completed=orders.filter(o=>o.professional==='courier'&&o.status==='completed');
 return `<div class="content-page food-page delivery-courier-page">${head('Painel do entregador','Comida pronta, próxima entrega',false)}<div class="professional-head"><div><span class="small">Olá, ${esc(p.name)}</span><h2>${state.online.courier?'Pronto para entregar':'Vamos começar?'}</h2><p>${state.online.courier?'Disponível para entregas de comida na demo':'Fique online para receber ofertas de teste'}</p></div><button class="switch ${state.online.courier?'on':''}" role="switch" aria-checked="${state.online.courier}" data-action="online"><span>${state.online.courier?'Online':'Offline'}</span><i></i></button></div><div class="delivery-courier-metrics"><div><span>Fretes concluídos · demo</span><strong>${money(earnings('courier'))}</strong></div><div><span>Entregas concluídas</span><strong>${completed.length}</strong></div><div><span>Avaliação fictícia</span><strong>4,9 <small>★</small></strong></div></div>${active?foodWorkCard(active):`<div class="section-title"><h2>Ofertas disponíveis</h2><button class="text-button" data-action="restore-queue">Atualizar</button></div>${!state.online.courier?`<div class="card courier-focus-empty"><div class="courier-focus-art"><img src="./assets/delivery-scooter.png" alt="Scooter de entrega ilustrativa"></div><h3>Você está offline</h3><p>Ative o botão acima. A oferta aparece quando o restaurante concluir o preparo.</p></div>`:queue.length?`<div class="stack">${queue.map(foodOfferCard).join('')}</div>`:`<div class="card courier-focus-empty"><div class="courier-focus-art"><img src="./assets/delivery-scooter.png" alt="Scooter de entrega ilustrativa"></div><h3>Pronto para o próximo pedido</h3><p>A oferta chega aqui quando a cozinha marcar o pedido como pronto.</p><button class="secondary" data-action="role" data-role="client">Criar pedido como Cliente</button></div>`}`}<p class="tracking-demo-caption">${icon('lab')}Entrega de cerveja ainda está em breve. As ofertas e ações de entrega são simuladas neste navegador.</p></div>`;
}
function deliveryWalletPage(){
 if(state.role==='restaurant')return restaurantWalletPage();if(state.role==='admin'){adminView='finance';return deliveryAdminPage();}
 const pro=state.role==='courier',orders=visibleOrders(state).filter(o=>o.food&&(pro?o.professional==='courier'&&o.status==='completed':true)),total=orders.filter(o=>o.food!.paymentStatus==='approved').reduce((s,o)=>s+(pro?o.food!.deliveryFee:o.price),0);
 return `<div class="content-page food-page">${head(pro?'Seus ganhos de entrega':'Pagamentos de teste',pro?'Fretes ilustrativos de pedidos concluídos':'Sem cartão, Pix ou cobrança real')}<div class="wallet-hero"><p>${pro?'Fretes concluídos · demo':'Pedidos com pagamento fictício aprovado'}</p><h1>${money(total)}</h1><p>${orders.length} ${orders.length===1?'pedido':'pedidos'} ${pro?'concluídos':'de comida'} nesta demonstração</p></div><div class="notice">${pro?'Frete ilustrativo de R$ 8,00 por pedido de comida entregue. Não há dinheiro real ou saque.':'A confirmação de pagamento acontece apenas dentro do pedido de comida. Nenhum dinheiro é movimentado.'}</div><div class="card food-footnote"><h3>${pro?'Entregas concluídas':'Histórico de pagamentos'}</h3>${orders.length?orders.map(o=>`<div class="transaction"><div class="help-icon">${icon(pro?'bike':'orders')}</div><div class="grow"><strong>${o.id} · ${o.food!.restaurantName}</strong><p>${date(o.created)} · ${o.food!.paymentStatus==='approved'?'Aprovado na demo':'Cancelado na demo'}</p></div><strong>${money(pro?o.food!.deliveryFee:o.price)}</strong></div>`).join(''):'<p class="muted food-footnote">Seus pedidos de comida aparecerão aqui.</p>'}</div></div>`;
}
function deliveryProfilePage(){
 if(state.role==='restaurant')return restaurantProfilePage();const role=state.role as FoodRole,profile=state.demoProfiles[role],name=profile?.name||'Admin Demo';
 return `<div class="content-page food-page">${head('Seu perfil','Uma identidade fictícia para testar entregas')}<div class="card"><div class="profile-hero"><div class="avatar">${esc(name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><h2>${esc(name)}</h2><p class="small muted food-footnote">${state.role==='courier'?'Entregador':state.role==='client'?'Cliente':'Admin'} · Conta de demonstração</p></div></div><div class="profile-menu">${(profile?[['user',profile.registered?'Editar cadastro demo':'Testar cadastro','food-register']]:[]).concat([['pin','Endereços fictícios','addresses'],['bell','Notificações','notifications'],['help','Como testar o TitoJá','help'],['logout','Sair da demonstração','logout']]).map(([i,t,a])=>`<button data-action="${a}">${icon(i)}${t}${icon('chevron')}</button>`).join('')}</div></div><div class="notice food-footnote">Não envie documentos, senhas ou dados bancários reais. Os cadastros ficam apenas neste navegador.</div></div>`;
}
function deliveryAdminPage(){
 const tabs=focusAdminTabs();if(!tabs.some(t=>t[0]===adminView))adminView='dashboard';const orders=visibleOrders(state),done=orders.filter(o=>o.food&&o.status==='completed'),active=orders.filter(o=>!['completed','cancelled'].includes(o.status)),total=done.reduce((s,o)=>s+o.price,0),products=done.reduce((s,o)=>s+o.food!.subtotal,0),freight=done.reduce((s,o)=>s+o.food!.deliveryFee,0);let body='';
 if(adminView==='dashboard')body=`<div class="metrics"><div class="metric"><span>Pedidos de comida</span><strong>${orders.length}</strong><small>Nesta demonstração</small></div><div class="metric"><span>Em andamento</span><strong>${active.length}</strong><small>Estado compartilhado</small></div><div class="metric"><span>Concluídos</span><strong>${done.length}</strong><small>Entrega confirmada</small></div><div class="metric"><span>Total concluído</span><strong>${money(total)}</strong><small>Valor fictício</small></div></div><div class="focus-service-summary"><div>${icon('orders')}<span><strong>Comida</strong><small>Fluxo de teste disponível</small></span><span class="status completed">Ativo</span></div><div>${icon('clock')}<span><strong>Entrega de cerveja</strong><small>Pedidos ainda indisponíveis</small></span><span class="demo-pill">Em breve</span></div></div><div class="section-title food-footnote"><h3>Últimos pedidos</h3></div><div class="stack">${orders.length?orders.slice(0,5).map(orderCard).join(''):empty('Nenhum pedido de comida ainda','Crie um pedido no perfil Cliente para começar.')}</div>`;
 else if(adminView==='users')body=`<div class="card"><h3>Perfis da demonstração</h3>${table(['Perfil','Nome fictício','Cadastro'],(['client','restaurant','courier'] as FoodRole[]).map(r=>[({client:'Cliente',restaurant:'Restaurante',courier:'Entregador'})[r],esc(state.demoProfiles[r].name),state.demoProfiles[r].registered?'Cadastro demo salvo':'Perfil de teste disponível']))}<div class="notice info">Cadastro local e simulado. Nenhuma conta ou documento real.</div></div>`;
 else if(adminView==='deliveries')body=`<div class="stack">${orders.length?orders.map(orderCard).join(''):empty('Nenhum pedido por aqui','Faça um pedido de comida no perfil Cliente.')}</div>`;
 else if(adminView==='finance')body=`<div class="metrics"><div class="metric"><span>Total concluído</span><strong>${money(total)}</strong></div><div class="metric"><span>Produtos</span><strong>${money(products)}</strong></div><div class="metric"><span>Fretes ilustrativos</span><strong>${money(freight)}</strong></div><div class="metric"><span>Em andamento</span><strong>${money(active.reduce((s,o)=>s+o.price,0))}</strong></div></div><div class="card"><h3>Pedidos concluídos</h3>${table(['Pedido','Produtos','Frete','Total'],done.map(o=>[o.id,money(o.food!.subtotal),money(o.food!.deliveryFee),money(o.price)]))}<div class="notice">Valores fictícios, sem comissão comercial definida. Produtos e frete são separados; não há repasse ou pagamento real.</div></div>`;
 else if(adminView==='payments')body=`<div class="card"><h3>Pagamentos de demonstração</h3>${table(['Pedido','Método','Total','Situação'],orders.filter(o=>o.food).map(o=>[o.id,'Simulação local',money(o.price),o.food!.paymentStatus==='approved'?'Aprovado na demo':'Cancelado na demo']))}<div class="notice info">A aprovação é explícita no checkout. Não existe conexão com Pix, cartão ou gateway.</div></div>`;
 else if(adminView==='ratings')body=`<div class="card"><h3>Avaliações de entregas</h3>${orders.filter(o=>o.rating).map(o=>`<div class="transaction"><div class="help-icon">${icon('star')}</div><div class="grow"><strong>${o.id} · Comida</strong><p>${o.tags?.map(esc).join(' · ')||'Sem comentários'}</p></div><strong>${'★'.repeat(o.rating||0)}</strong></div>`).join('')||'<p class="muted food-footnote">Ainda não há avaliações de pedidos de comida.</p>'}</div>`;
 else if(adminView==='reports')body=`<div class="card"><h3>Relatório de pedidos</h3><p class="muted food-footnote">Exporte os ${orders.length} pedidos das categorias ativas desta demonstração.</p><button class="primary food-footnote" data-action="export">${icon('download')}Baixar relatório demo</button><div class="notice info food-footnote">O arquivo é gerado localmente, sem enviar dados para outro serviço.</div></div>`;
 else body=`<div class="card"><h3>Configurações da demonstração</h3><div class="transaction"><div class="grow"><strong>Notificações internas</strong><p>Atualizações dentro do aplicativo</p></div><button class="switch ${state.settings.notifications?'on':''}" role="switch" aria-checked="${state.settings.notifications}" data-action="setting"><i></i></button></div><div class="summary-line"><span>Cidade de teste</span><strong>Castanhal · PA</strong></div><div class="summary-line"><span>Categorias em destaque</span><strong>Comida e cerveja</strong></div><div class="summary-line"><span>Armazenamento</span><strong>Neste navegador</strong></div><div class="notice info food-footnote">Pedidos, perfis e pagamentos são fictícios. Entrega de cerveja está em breve.</div></div>`;
 return `<div class="admin-layout"><nav class="admin-nav" aria-label="Administração">${tabs.map(([v,i,l])=>`<button class="${v===adminView?'active':''}" data-action="admin" data-value="${v}">${icon(i)}${l}</button>`).join('')}</nav><section class="admin-content">${head(tabs.find(t=>t[0]===adminView)?.[2]||'Painel','Comida e cerveja · ambiente de demonstração',false)}${body}</section></div>`;
}
